package io.github.ericonyu.qimen4kotlin;

import com.tyme.lunar.LunarDay;
import com.tyme.solar.SolarTerm;
import com.tyme.solar.SolarTime;
import com.tyme.sixtycycle.SixtyCycleHour;
import java.time.DateTimeException;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.util.*;

public final class Qimen {
  private static final String[] GAN={"甲","乙","丙","丁","戊","己","庚","辛","壬","癸"}, ZHI={"子","丑","寅","卯","辰","巳","午","未","申","酉","戌","亥"};
  private static final String[] TERMS={"小寒","大寒","立春","雨水","惊蛰","春分","清明","谷雨","立夏","小满","芒种","夏至","小暑","大暑","立秋","处暑","白露","秋分","寒露","霜降","立冬","小雪","大雪","冬至"};
  private static final String[] NAMES={"坎","坤","震","巽","中","乾","兑","艮","离"}, DIRECTIONS={"正北","西南","正东","东南","中央","西北","正西","东北","正南"}, ELEMENTS={"水","土","木","木","土","金","金","土","火"};
  private static final String[] EARTH={"戊","己","庚","辛","壬","癸","丁","丙","乙"}, STARS={"天蓬星","天芮星","天冲星","天辅星","天禽星","天心星","天柱星","天任星","天英星"}, DOORS={"休门","死门","伤门","杜门","","开门","惊门","生门","景门"}, DEITIES={"值符","螣蛇","太阴","六合","白虎","玄武","九地","九天"};
  private static final int[] CIRCLE={3,8,1,6,5,0,7,2};
  private static final Map<String,String> GAN_ELEMENT=map("甲","木","乙","木","丙","火","丁","火","戊","土","己","土","庚","金","辛","金","壬","水","癸","水");
  private static final Map<String,Integer> BRANCH_PALACE=intMap("子",0,"丑",7,"寅",7,"卯",2,"辰",3,"巳",3,"午",8,"未",1,"申",1,"酉",6,"戌",5,"亥",5);
  private static final Map<String,String> YIMA=map("申","寅","子","寅","辰","寅","寅","申","午","申","戌","申","亥","巳","卯","巳","未","巳","巳","亥","酉","亥","丑","亥");
  private static final Map<String,String> RUMU=map("甲","未","乙","未","丙","戌","丁","戌","戊","戌","庚","丑","辛","丑","壬","辰","癸","辰");
  private static final Map<String,String> DOOR_ELEMENT=map("休门","水","死门","土","伤门","木","杜门","木","开门","金","惊门","金","生门","土","景门","火");
  private static final Map<String,String> FORMATIONS=map("乙+丙","奇仪相佐","乙+丁","奇仪相佐","丙+丁","星月相会","丙+戊","飞鸟跌穴","丁+戊","青龙返首","乙+戊","日出扶桑","丙+己","天遁","丁+壬","地遁","丁+己","人遁","丙+壬","神遁","乙+癸","鬼遁","庚+乙","太白入荧","庚+丙","太白入荧","庚+丁","太白入荧","辛+乙","白虎猖狂","乙+辛","龙逃走","癸+丁","腾蛇夭矫","癸+丙","蛇矫入火","庚+戊","值符飞宫","庚+壬","上格","庚+癸","大格","丁+癸","玉女守门","戊+壬","小格","戊+癸","刑格","己+庚","刑格入狱","辛+壬","凶蛇入刑");
  private Qimen() {}
  private static Map<String,String> map(String... values){Map<String,String> r=new LinkedHashMap<>();for(int i=0;i<values.length;i+=2)r.put(values[i],values[i+1]);return r;}
  private static Map<String,Integer> intMap(Object... values){Map<String,Integer> r=new LinkedHashMap<>();for(int i=0;i<values.length;i+=2)r.put((String)values[i],(Integer)values[i+1]);return r;}
  private static List<String> jiazi(){List<String> r=new ArrayList<>();for(int i=0;i<60;i++)r.add(GAN[i%10]+ZHI[i%12]);return r;}
  private static int index(String[] a,String v){return Arrays.asList(a).indexOf(v);} private static int index(int[] a,int v){for(int i=0;i<a.length;i++)if(a[i]==v)return i;return -1;}
  private static int mod(int n,int d){return (n%d+d)%d;} private static int abs(int n){return n<0?-n:n;}
  private static <T> List<T> rotate(List<T> a,int n){int x=mod(n,a.size());List<T> r=new ArrayList<>(a.subList(x,a.size()));r.addAll(a.subList(0,x));return r;}
  private static int inputInt(Map<String,Object> input,String key,boolean optional){Object v=input.get(key);if(v==null&&optional)return 0;if(!(v instanceof Number)||((Number)v).doubleValue()!=((Number)v).intValue())throw new IllegalArgumentException(key+" 必须是整数");return ((Number)v).intValue();}
  private static String season(String b){if("寅卯".contains(b))return "春";if("巳午".contains(b))return "夏";if("辰戌丑未".contains(b))return "四季土";if("申酉".contains(b))return "秋";return "冬";}
  private static Map<String,String> state(String season){if(season.equals("春"))return map("木","旺","火","相","水","休","金","囚","土","死");if(season.equals("夏"))return map("火","旺","土","相","木","休","水","囚","金","死");if(season.equals("四季土"))return map("土","旺","金","相","火","休","木","囚","水","死");if(season.equals("秋"))return map("金","旺","水","相","土","休","火","囚","木","死");return map("水","旺","木","相","金","休","土","囚","火","死");}
  private static Map<String,Object> kong(String pillar){List<String> jz=jiazi();int start=jz.indexOf(pillar)/10*10;Set<String> used=new HashSet<>();for(int i=start;i<start+10;i++)used.add(jz.get(i).substring(1));List<String> branches=new ArrayList<>();List<Integer> palaces=new ArrayList<>();for(String b:ZHI)if(!used.contains(b)){branches.add(b);palaces.add(BRANCH_PALACE.get(b)+1);}Map<String,Object> r=new LinkedHashMap<>();r.put("branches",branches);r.put("palaces",palaces);return r;}
  private static String yearChinese(int year){String d="〇一二三四五六七八九",s=String.valueOf(year),r="";for(char c:s.toCharArray())r+=d.charAt(c-'0');return r;}
  private static String format(SolarTime t){return String.format("%04d-%02d-%02d %02d:%02d",t.getYear(),t.getMonth(),t.getDay(),t.getHour(),t.getMinute());}

  public static Map<String,Object> calculate(Map<String,Object> input){
    int y=inputInt(input,"year",false),m=inputInt(input,"month",false),d=inputInt(input,"day",false),h=inputInt(input,"hour",false),minute=inputInt(input,"minute",true);if(y<1900||y>2100)throw new IllegalArgumentException("year 必须在 1900 到 2100 之间");if(h<0||h>23||minute<0||minute>59)throw new IllegalArgumentException("日期无效");LocalDateTime original;try{original=LocalDateTime.of(y,m,d,h,minute);}catch(DateTimeException e){throw new IllegalArgumentException("日期无效",e);}Object tz=input.get("timezone");if(tz!=null)try{ZoneId.of(String.valueOf(tz));}catch(Exception e){throw new IllegalArgumentException("timezone 无效",e);}
    String juMethod=String.valueOf(input.getOrDefault("juMethod","chaibu"));if(!juMethod.equals("chaibu")&&!juMethod.equals("maoshan"))throw new IllegalArgumentException("juMethod 无效");if(input.containsKey("panType")&&!"zhuan".equals(input.get("panType")))throw new IllegalArgumentException("目前仅支持转盘奇门");
    LocalDateTime effective=h==23?original.plusHours(1):original;SolarTime solar=SolarTime.fromYmdHms(effective.getYear(),effective.getMonthValue(),effective.getDayOfMonth(),effective.getHour(),effective.getMinute(),0);SixtyCycleHour sc=solar.getSixtyCycleHour();String[] pillars={sc.getYear().toString(),sc.getMonth().toString(),sc.getDay().toString(),sc.getSixtyCycle().toString()};SolarTerm term=solar.getTerm();SolarTerm next=term.next(1);int rotate=mod(index(TERMS,term.toString())-5,24);int element=(jiazi().indexOf(pillars[2])/5)%3;if(juMethod.equals("maoshan")){element=Math.min(2,solar.subtract(term.getJulianDay().getSolarTime())/5);}
    int ri=((int)(rotate/3.0+2))%8,direction=ri<4?1:-1,round=mod(new int[]{1,8,3,4,9,2,7,6}[ri]+direction*(rotate%3)+direction*6*element+17,9);round=(round+1)*direction;
    String[] earth=new String[9];List<Integer> order=new ArrayList<>();for(int i=0;i<9;i++)order.add(i);int start=round-1;if(round<0){start++;Collections.reverse(order);}List<Integer> earthPalaces=rotate(order,start);for(int i=0;i<9;i++)earth[earthPalaces.get(i)]=EARTH[i];
    List<String> jz=jiazi();int hourIndex=jz.indexOf(pillars[3]);String conceal=EARTH[hourIndex/10];int concealPalace=index(earth,conceal),middle="ji_wugong".equals(input.get("zhiFuJiGong"))?1:(round>0?7:1),symbolIndex=concealPalace,mandate=concealPalace==4?middle:concealPalace;String hourOrigin=pillars[3].substring(0,1).equals("甲")?conceal:pillars[3].substring(0,1);int offset=mod(index(CIRCLE,concealPalace)-index(CIRCLE,index(earth,hourOrigin)),8);String[] starBoard=new String[9],heaven=new String[9];List<Integer> ring=new ArrayList<>();for(int p:CIRCLE)ring.add(p);List<Integer> rotatedStars=rotate(ring,offset);for(int i=0;i<8;i++){int p=CIRCLE[i],originPalace=rotatedStars.get(i);starBoard[p]=STARS[originPalace];heaven[p]=earth[originPalace];}starBoard[4]="";heaven[4]="";
    int branch=index(ZHI,pillars[3].substring(1)),lead=index(ZHI,jz.get(hourIndex/10*10).substring(1)),timeOffset=mod(branch-lead,12),doorTarget=mod(concealPalace+timeOffset*direction,9);if(doorTarget==4)doorTarget=middle;int doorOffset=index(CIRCLE,mandate)-index(CIRCLE,doorTarget);String[] doorBoard=new String[9];List<Integer> rotatedDoors=rotate(ring,doorOffset);for(int i=0;i<8;i++)doorBoard[CIRCLE[i]]=DOORS[rotatedDoors.get(i)];doorBoard[4]="";
    String symbolName=STARS[symbolIndex];int symbolPalace=index(starBoard,symbolName),deityOffset;List<String> deityOrder=new ArrayList<>(Arrays.asList(DEITIES));if(round<0)Collections.reverse(deityOrder);deityOffset=mod(index(CIRCLE,symbolPalace)-deityOrder.indexOf("值符"),8);String[] deityBoard=new String[9];List<String> rotatedDeities=rotate(deityOrder,-deityOffset);for(int i=0;i<8;i++)deityBoard[CIRCLE[i]]=rotatedDeities.get(i);deityBoard[4]="";
    String season=season(pillars[1].substring(1));Map<String,String> states=state(season);Map<String,Object> dayKong=kong(pillars[2]),hourKong=kong(pillars[3]);String yima=YIMA.get(pillars[2].substring(1));int yimaPalace=BRANCH_PALACE.get(yima);Map<Integer,Integer> opposite=new HashMap<>();opposite.put(0,8);opposite.put(8,0);opposite.put(1,7);opposite.put(7,1);opposite.put(2,6);opposite.put(6,2);opposite.put(3,5);opposite.put(5,3);List<Object> palaces=new ArrayList<>(),global=new ArrayList<>();
    for(int i=0;i<9;i++){List<String> fs=new ArrayList<>();String f=FORMATIONS.get(heaven[i]+"+"+earth[i]);if(i!=4&&f!=null)fs.add(f);int si=index(STARS,starBoard[i]);if(si==i)fs.add("伏吟");if(opposite.get(si)!=null&&opposite.get(si)==i)fs.add("反吟");for(String x:fs)global.add(NAMES[i]+"宫: "+x);int mu=RUMU.containsKey(heaven[i])?BRANCH_PALACE.get(RUMU.get(heaven[i])):-1;Map<String,Object> p=new LinkedHashMap<>();p.put("palaceIndex",i+1);p.put("palaceName",NAMES[i]);p.put("direction",DIRECTIONS[i]);p.put("element",ELEMENTS[i]);p.put("earthStem",earth[i]);p.put("earthStemElement",GAN_ELEMENT.getOrDefault(earth[i],""));p.put("heavenStem",heaven[i]);p.put("heavenStemElement",GAN_ELEMENT.getOrDefault(heaven[i],""));p.put("star",starBoard[i]);p.put("starElement",si<0?"":ELEMENTS[si]);p.put("gate",doorBoard[i]);p.put("gateElement",DOOR_ELEMENT.getOrDefault(doorBoard[i],""));p.put("deity",deityBoard[i]);p.put("formations",fs);p.put("stemWangShuai",states.getOrDefault(GAN_ELEMENT.get(heaven[i]),""));p.put("elementState",states.get(ELEMENTS[i]));p.put("isKongWang",((List<?>)dayKong.get("palaces")).contains(i+1)||((List<?>)hourKong.get("palaces")).contains(i+1));p.put("isYiMa",i==yimaPalace);p.put("isRuMu",i==mu);palaces.add(p);}
    LunarDay lunar=SolarTime.fromYmdHms(y,m,d,h,minute,0).getLunarHour().getLunarDay();Map<String,Object> dateInfo=new LinkedHashMap<>();dateInfo.put("solarDate",String.format("%04d-%02d-%02d",y,m,d));dateInfo.put("lunarDate",yearChinese(y)+"年"+lunar.getLunarMonth().getName()+lunar.getName());dateInfo.put("solarTerm",term.toString());dateInfo.put("solarTermRange",format(term.getJulianDay().getSolarTime())+" ~ "+format(next.getJulianDay().getSolarTime()));Map<String,Object> siZhu=new LinkedHashMap<>();siZhu.put("year",pillars[0]);siZhu.put("month",pillars[1]);siZhu.put("day",pillars[2]);siZhu.put("hour",pillars[3]);Map<String,Object> result=new LinkedHashMap<>();result.put("algorithmVersion","qimen-zhuanpan-chaibu-v1");result.put("dateInfo",dateInfo);result.put("siZhu",siZhu);result.put("dunType",round>0?"yang":"yin");result.put("juNumber",abs(round));result.put("yuan",new String[]{"上元","中元","下元"}[element]);result.put("xunShou","甲"+jz.get(hourIndex/10*10).substring(1));result.put("zhiFu",linked("star",symbolName,"palace",symbolPalace+1));result.put("zhiShi",linked("gate",DOORS[mandate],"palace",index(doorBoard,DOORS[mandate])+1));result.put("palaces",palaces);result.put("kongWang",linked("dayKong",dayKong,"hourKong",hourKong));result.put("yiMa",linked("branch",yima,"palace",yimaPalace+1));result.put("globalFormations",global);result.put("panType","转盘");result.put("juMethod",juMethod.equals("maoshan")?"茅山法":"拆补法");if(input.containsKey("question"))result.put("question",input.get("question"));Map<String,Object> phase=new LinkedHashMap<>();for(String g:GAN)phase.put(g,states.get(GAN_ELEMENT.get(g)));result.put("monthPhase",phase);return result;
  }
  private static Map<String,Object> linked(Object... values){Map<String,Object> r=new LinkedHashMap<>();for(int i=0;i<values.length;i+=2)r.put((String)values[i],values[i+1]);return r;}
  private static Object dash(Object v){return "".equals(v)?"-":v;}
  @SuppressWarnings("unchecked") public static Map<String,Object> canonical(Map<String,Object> input){Map<String,Object> r=calculate(input),s=(Map<String,Object>)r.get("siZhu"),zf=(Map<String,Object>)r.get("zhiFu"),zs=(Map<String,Object>)r.get("zhiShi");Map<String,Object> basic=linked("四柱",s.get("year")+" "+s.get("month")+" "+s.get("day")+" "+s.get("hour"),"节气",((Map<String,Object>)r.get("dateInfo")).get("solarTerm"),"局式",("yang".equals(r.get("dunType"))?"阳遁":"阴遁")+r.get("juNumber")+"局","三元",r.get("yuan"),"旬首",r.get("xunShou"),"值符",zf.get("star"),"值使",zs.get("gate"));if(r.containsKey("question"))basic.put("占问",r.get("question"));List<Object> board=new ArrayList<>();Map<String,Object> kw=(Map<String,Object>)r.get("kongWang");for(Object raw:(List<Object>)r.get("palaces")){Map<String,Object> p=(Map<String,Object>)raw;int i=(Integer)p.get("palaceIndex");List<String> status=new ArrayList<>();if(((List<Integer>)((Map<String,Object>)kw.get("dayKong")).get("palaces")).contains(i))status.add("日空");if(((List<Integer>)((Map<String,Object>)kw.get("hourKong")).get("palaces")).contains(i))status.add("时空");if((Boolean)p.get("isYiMa"))status.add("驿马");if((Boolean)p.get("isRuMu"))status.add("入墓");if(i==5)status=new ArrayList<>(Collections.singletonList("寄宫参看对应宫位"));Map<String,Object> item=linked("宫名",p.get("palaceName"),"宫位序号",i,"宫位",p.get("palaceName")+String.valueOf(i),"宫位五行",p.get("element"),"八神",dash(p.get("deity")),"九星",dash(p.get("star")));if(!"".equals(p.get("starElement")))item.put("九星五行",p.get("starElement"));item.put("八门",dash(p.get("gate")));if(!"".equals(p.get("gateElement")))item.put("八门五行",p.get("gateElement"));item.put("天盘天干",dash(p.get("heavenStem")));item.put("地盘天干",dash(p.get("earthStem")));item.put("宫位状态",status);board.add(item);}return linked("基本信息",basic,"九宫盘",board);}
}
